pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzzed parameter is the interface id to query
    function testFuzz_property(bytes4 interfaceId) public {
        // no tight assumptions; keep domain wide so fuzzer can find the mutant-distinguishing id

        // call supportsInterface and record whether call succeeds and returned value
        bool ok;
        bool ret;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property the reference satisfies for ALL interfaceId values:
        // If interfaceId == type(IAccessControl).interfaceId OR interfaceId == type(IERC165).interfaceId
        // then supportsInterface must return true; otherwise it may be false.
        // We express that as: for the two well-known ids, the call must succeed and return true.
        // This assertion reads c's public behaviour and will hold on reference but fail on mutant
        // because the mutant returns false for type(IERC165).interfaceId.

        // Build the two well-known ids
        bytes4 iaAccessControl = type(IAccessControl).interfaceId;
        bytes4 iaERC165 = type(IERC165).interfaceId;

        // If the fuzzed interfaceId equals one of the known ones, then the call must succeed and return true.
        // We encode that requirement but only assert once (using a boolean that captures the condition).
        bool requirementHolds;
        if (interfaceId == iaAccessControl || interfaceId == iaERC165) {
            requirementHolds = (ok && ret == true);
        } else {
            // For other ids, reference may return false; we don't require true. So always consider requirement satisfied.
            requirementHolds = true;
        }

        assertTrue(requirementHolds);
    }
}

