        // behavior; the fuzzer is free to set interfaceId to type(IERC165).interfaceId, which the
        // reference returns true for but the mutant returns false, causing the test to fail on the mutant.

        bytes4 IERC165_id = type(IERC165).interfaceId;

        // Exact single assertion required: it reads c via supportsInterface and enforces the universal rule.
        if (interfaceId == IERC165_id) {
            assertTrue(ok && ret);
        }
    }
